                    visited[v] = (u, dist + 1)
                    queue.append(v)
                elif v != visited[u][0]:
                    cycle_len = dist + visited[v][1] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def is_3_colorable_fast(edges, n):
    """Check 3-colorability."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and color[neighbor] == c:
                    valid = False
                    break
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                color[v] = -1
        return False

